const STORAGE_KEY = "xiaoyou-tavern-preset"
const STYLE_ID = "xiaoyou-tavern-theme"
const LABELS = { paper: "米黄", night: "暖黑" }

function readPreset() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY)
    if (saved === "night" || saved === "paper") return saved
  } catch {
    /* ignore */
  }
  return "paper"
}

function applyPreset(id) {
  const css = PRESETS[id] || PRESETS.paper
  const head = document.head
  if (!head) return
  let style = document.getElementById(STYLE_ID)
  if (!style) {
    style = document.createElement("style")
    style.id = STYLE_ID
    head.appendChild(style)
  }
  style.textContent = css
  head.appendChild(style)
  const button = document.getElementById("xiaoyou-preset-switch")
  if (button) {
    const next = id === "paper" ? "night" : "paper"
    button.textContent = LABELS[id]
    button.dataset.preset = id
    button.title = "切换到" + LABELS[next]
    button.setAttribute("aria-label", button.title)
  }
}

applyPreset(readPreset())

const NAV_LABELS = ["采样", "接口", "格式", "世界书", "用户设置", "背景", "扩展", "人格", "角色"]

function ensureSwitch() {
  if (document.getElementById("xiaoyou-preset-switch")) return
  const button = document.createElement("button")
  button.type = "button"
  button.id = "xiaoyou-preset-switch"
  button.addEventListener("mousedown", (event) => {
    if (document.querySelector(".drawer-content.openDrawer")) event.stopPropagation()
  })
  button.addEventListener("click", (event) => {
    event.preventDefault()
    event.stopPropagation()
    const next = button.dataset.preset === "night" ? "paper" : "night"
    try {
      localStorage.setItem(STORAGE_KEY, next)
    } catch {
      /* ignore */
    }
    applyPreset(next)
  })
  document.body.appendChild(button)
  applyPreset(readPreset())
}

function ensureChrome() {
  if (!document.body) return
  document.body.classList.add("xiaoyou-thread")
  ensureSwitch()
  const holder = document.getElementById("top-settings-holder")
  if (holder && !document.getElementById("xiaoyou-nav-toggle")) {
    const toggle = document.createElement("button")
    toggle.type = "button"
    toggle.id = "xiaoyou-nav-toggle"
    toggle.setAttribute("aria-label", "菜单")
    toggle.setAttribute("aria-expanded", "false")
    toggle.textContent = "…"
    toggle.addEventListener("mousedown", (event) => {
      if (document.querySelector(".drawer-content.openDrawer")) event.stopPropagation()
    })
    toggle.addEventListener("click", (event) => {
      event.preventDefault()
      event.stopPropagation()
      if (document.querySelector(".drawer-content.openDrawer")) return
      const open = document.body.classList.toggle("xiaoyou-nav-open")
      toggle.setAttribute("aria-expanded", open ? "true" : "false")
    })
    holder.appendChild(toggle)
    holder.querySelectorAll(":scope > .drawer .drawer-icon").forEach((icon, index) => {
      const label = NAV_LABELS[index] || icon.getAttribute("title") || "菜单"
      icon.setAttribute("data-xiaoyou-label", label)
    })
    holder.addEventListener("click", (event) => {
      const target = event.target
      if (!(target instanceof Element) || !target.closest(".drawer-icon")) return
      document.body.classList.remove("xiaoyou-nav-open")
      toggle.setAttribute("aria-expanded", "false")
    })
    document.addEventListener("click", (event) => {
      const target = event.target
      if (!(target instanceof Element)) return
      if (holder.contains(target) || target.closest("#xiaoyou-preset-switch")) return
      if (target.closest(".drawer-content, .openDrawer, .select2-container, .select2-dropdown, .popup")) return
      if (!document.body.classList.contains("xiaoyou-nav-open")) return
      document.body.classList.remove("xiaoyou-nav-open")
      toggle.setAttribute("aria-expanded", "false")
    })
  }

  if (!document.getElementById("xiaoyou-thread-header")) {
    const header = document.createElement("header")
    header.id = "xiaoyou-thread-header"
    header.hidden = true
    header.innerHTML =
      '<button type="button" id="xiaoyou-thread-back" aria-label="返回">' +
      '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15.2 4.8 8 12l7.2 7.2" fill="none" stroke="currentColor" stroke-width="2.15" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
      "</button>" +
      '<div id="xiaoyou-thread-identity"><img id="xiaoyou-thread-avatar" alt=""><div id="xiaoyou-thread-name"></div></div>'
    document.body.appendChild(header)
    document.getElementById("xiaoyou-thread-back")?.addEventListener("click", () => {
      const close = document.querySelector("#options a#option_close_chat")
      if (close instanceof HTMLElement) close.click()
    })
  }

  const field = document.querySelector("#send_textarea")
  if (field instanceof HTMLTextAreaElement) {
    field.setAttribute("connected_text", "写一条消息")
    field.setAttribute("no_connection_text", "写一条消息")
    if (!field.value) field.placeholder = "写一条消息"
  }
}

async function syncThreadHeader() {
  const header = document.getElementById("xiaoyou-thread-header")
  const nameEl = document.getElementById("xiaoyou-thread-name")
  const img = document.getElementById("xiaoyou-thread-avatar")
  if (!header || !nameEl || !(img instanceof HTMLImageElement)) return

  let name = ""
  let avatar = ""
  try {
    const { getContext } = await import("../../../st-context.js")
    const ctx = getContext()
    const character = ctx.characters?.[ctx.characterId]
    name = ctx.name2 || character?.name || ""
    if (character?.avatar && character.avatar !== "none") {
      avatar = "/thumbnail?type=avatar&file=" + encodeURIComponent(character.avatar)
    }
  } catch {
    /* fall through to the message row */
  }

  const sample = document.querySelector('#chat .mes[is_user="false"][is_system="false"]')
  if (!name && sample) name = sample.getAttribute("ch_name") || ""
  if (!avatar && sample) {
    const found = sample.querySelector("img")
    if (found instanceof HTMLImageElement && found.getAttribute("src")) avatar = found.src
  }

  if (!name && !avatar) {
    header.hidden = true
    return
  }
  header.hidden = false
  nameEl.textContent = name
  if (avatar) img.src = avatar
  img.alt = name || "角色"
}

function watchThread() {
  ensureChrome()
  installThreadBehavior()
  void syncThreadHeader()
  const chat = document.getElementById("chat")
  if (chat && chat.dataset.xiaoyouWatch !== "1") {
    chat.dataset.xiaoyouWatch = "1"
    const observer = new MutationObserver(() => {
      ensureChrome()
      void syncThreadHeader()
    })
    observer.observe(chat, { childList: true })
  }
  void import("../../../st-context.js")
    .then(({ getContext }) => {
      const ctx = getContext()
      const source = ctx.eventSource
      const types = ctx.eventTypes
      if (!source || !types || source.__xiaoyouTheme) return
      source.__xiaoyouTheme = true
      const refresh = () => {
        ensureChrome()
        void syncThreadHeader()
      }
      source.on(types.CHAT_CHANGED, refresh)
      source.on(types.CHAT_LOADED, refresh)
      source.on(types.APP_READY, refresh)
    })
    .catch(() => {})
}

watchThread()
window.addEventListener("load", () => watchThread())
